  red = "#FF0033",
  red_dim = "#7A0019",
  magenta = "#FF2AA0",
  warning = "#FFB000",
  green = "#2FD08A",
  blue = "#5B6CFF",
  cyan = "#2BC8D9",
  bright_green = "#6BF0B4",
  bright_blue = "#8C98FF",
  bright_cyan = "#6FE6F2",
  bright_yellow = "#FFCB55",
  bright_black = "#3A3844",
  visual = "#4C0515",
  bright_black_text = "#98949C",
